class TaskBinding {record Payload(String name){}record Bound(int kind,Object stack){}static Object payload(String name){return new Payload(name);}static Object create(int kind,int n){return new Bound(kind,switch(kind){case 0->{IGenStack<String> stack=new ArrayStack<>(filledStrings(n));yield stack;}case 1->{IGenStack<Integer> stack=new ArrayStack<>(filledIntegers(n));yield stack;}default->{IGenStack<Payload> stack=new ArrayStack<>(filledPayloads(n));yield stack;}});}@SuppressWarnings("unchecked")static void push(Object q,Object value)throws Exception{Bound b=(Bound)q;switch(b.kind){case 0->{IGenStack<String>s=(IGenStack<String>)b.stack;s.push((String)value);}case 1->{IGenStack<Integer>s=(IGenStack<Integer>)b.stack;s.push((Integer)value);}default->{IGenStack<Payload>s=(IGenStack<Payload>)b.stack;s.push((Payload)value);}}}@SuppressWarnings("unchecked")static Object pop(Object q)throws Exception{Bound b=(Bound)q;return switch(b.kind){case 0->{IGenStack<String>s=(IGenStack<String>)b.stack;String value=s.pop();yield value;}case 1->{IGenStack<Integer>s=(IGenStack<Integer>)b.stack;Integer value=s.pop();yield value;}default->{IGenStack<Payload>s=(IGenStack<Payload>)b.stack;Payload value=s.pop();yield value;}};}static boolean full(Exception x){return x instanceof StackFullException;}static boolean empty(Exception x){return x instanceof StackEmptyException;}static String[]filledStrings(int n){String[]a=new String[n];java.util.Arrays.fill(a,"PRELOAD");return a;}static Integer[]filledIntegers(int n){Integer[]a=new Integer[n];java.util.Arrays.fill(a,-999);return a;}static Payload[]filledPayloads(int n){Payload[]a=new Payload[n];java.util.Arrays.fill(a,new Payload("PRELOAD"));return a;}}
